using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);
builder.Services.AddHostedService<HostedWorkers.ExactWorker>();
builder.Services.AddHostedService<HostedWorkers.BackgroundWorker>();
builder.Services.AddHostedService<HostedWorkers.RetryWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreProofWorker>();
builder.Services.AddHostedService<HostedWorkers.DirectSemaphoreWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreNegativeShapesWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreUnawaitedWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreLoopMismatchWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreBranchWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreConsumptionWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreReceiverWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreLookalikeWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreDynamicWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreExtensionWorker>();
builder.Services.AddHostedService<HostedWorkers.DerivedSemaphoreWorker>();
builder.Services.AddHostedService<HostedWorkers.SemaphoreNestedLoopWorker>();
builder.Services.AddHostedService<HostedWorkers.CancellationNegativeWorker>();
builder.Services.AddHostedService<HostedWorkers.TerminalWorker>();
